)
VALUES (
  45,
  4,
  'quiz_choice',
  '{"question":"Клиент на созвоне сообщает вам неожиданную новость: «The server is down!». Выберите грамматически точную и быструю реакцию уровня А2:","options":[{"id":"a","text":"Oh, really? I am going to restart it now.","is_correct":false},{"id":"b","text":"Oh, really? I''ll restart it right now.","is_correct":true},{"id":"c","text":"Oh, really? I restart it yesterday.","is_correct":false}],"explanation_if_wrong":"Правильный ответ - «Oh, really? I''ll restart it right now.». Ситуация требует мгновенного, спонтанного решения в момент речи, поэтому по правилам уровня А2 мы обязаны использовать глагол WILL (сокращенно — I''ll). Конструкция going to здесь не подходит, так как вы не планировали это падение заранее."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
