INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  46,
  1,
  'theory',
  '{"text":"🎬 ХАРАКТЕРИСТИКА КОМАНДЫ С LEXI: ВСТРЕЧАЮТ ПО ОДЁЖКЕ\n\nПривет! На связи Lexi. В бизнесе и разработке мы постоянно взаимодействуем с людьми: нанимаем новых программистов, знакомимся с инвесторами или распределяем задачи внутри команды. Умение четко и емко описать человека - это мощный инструмент для нетворкинга на уровне А2.\n\nСегодня мы научимся уверенно описывать как внешность (рост, волосы, стиль), так и характер (надежность, собранность, стрессоустойчивость). Мы разберем готовые наборы слов для ИТ-среды и раскроем одну коварную лингвистическую ловушку, в которую часто попадают студенты, когда пытаются спросить «Какой он человек?».\n\nВключайте видео! Мы разберем основные маркеры описания личности и научимся презентовать своих коллег с лучшей стороны.","video_url":"https://vk.com/video-230370533_456239072","vk_attachment":"video-230370533_456239072","button_text":"К теории описания ➡️"}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  46,
  2,
  'theory',
  '{"text":"✨ УРОК 46. АРХИТЕКТУРА ОПИСАНИЯ: TO BE ПРОТИВ HAVE GOT\n\nКогда мы описываем человека, наша грамматика разделяется на две строгие ветви:\n\n1. ОПИСАНИЕ ЧЕРТ И КАЧЕСТВ (Используем глагол TO BE)\nЕсли мы говорим о росте, телосложении или чертах характера, мы берем глагол am/is/are.\n• Внешность: He is tall (Он высокий), She is short (Она невысокого роста), He is athletic (Он атлетичного телосложения).\n• Характер (ИТ-топ для А2):\n- reliable [рилайэбл] - надежный (тот, кто не подведет с дедлайном).\n- organized [органайзд] - организованный / собранный.\n- creative [криэйтив] - творческий.\n- calm [кам] - спокойный / стрессоустойчивый.\nПример: Our manager is very organized and calm. (Наш менеджер очень собранный и спокойный).\n\n2. ОПИСАНИЕ ОСОБЕННОСТЕЙ (Используем конструкцию HAVE GOT)\nЕсли мы говорим о волосах, цвете глаз или конкретных деталях внешности, мы берем ''ve got / ''s got.\n• Волосы: dark hair (темные волосы), fair hair (светлые волосы), short hair (короткие волосы).\nПример: She has got dark hair and green eyes. (У нее темные волосы и зеленые глаза).\n\n🔥 ГЛАВНЫЙ СЕКРЕТ УРОВНЯ А2: ДВА КОВАРНЫХ ВОПРОСА\nЗапомни эту разницу раз и навсегда, это маркер твоей грамотности:\n• Вопрос А: What does he look like? (Как он выглядит внешне? - спрашиваем про рост, волосы, одежду).\n• Вопрос Б: What is he like? (Какой он по характеру? - слово like здесь переводится не как глагол нравиться, а как предлог подобия).","button_text":"Понятно, дальше ➡️"}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
