INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  50,
  3,
  'theory',
  '{"text":"📖 ЖИВОЙ МИКРО-ДИАЛОГ: ПОИСК ОФИСА В НЕЗНАКОМОМ РАЙОНЕ\n\nДавай послушаем, как основатель ИТ-компании Алекс пытается найти дорогу к новому офису крупных клиентов. Навигатор в его телефоне перестал обновлять карты, и Алекс обращается к местному жителю на улице:\n\nAlex: Excuse me, could you tell me the way to the digital office building? I have an important meeting there, but my map is offline.\nLocal: Oh, yes! Don''t worry, it is quite near here. Go straight ahead past the central bank.\nAlex: Okay, I go straight past the bank. What next?\nLocal: Then turn left at the traffic lights. Walk through the small park. \nAlex: Turn left at the lights and walk through the park. Got it.\nLocal: After the park, take the second turning on the right. The digital office building is opposite the big hotel. It is a huge glass building, you can''t miss it!\nAlex: Perfect! Thank you very much for your help.\nLocal: You''re welcome! Good luck with your meeting.\n\n🇷🇺 ПЕРЕВОД ДЛЯ ПРОВЕРКИ:\n\nАлекс: Извините, не могли бы вы подсказать дорогу к зданию цифрового офиса? У меня там важная встреча, но моя карта работает офлайн.\nМестный: О, да! Не переживайте, это совсем рядом отсюда. Идите прямо вперед мимо центрального банка.\nАлекс: Хорошо, я иду прямо мимо банка. Что дальше?\nМестный: Затем поверните налево на светофоре. Пройдите сквозь маленький парк.\nАлекс: Повернуть налево на светофоре и пройти через парк. Понял.\nМестный: После парка поверните на втором повороте направо. Здание цифрового офиса находится напротив большого отеля. Это огромное стеклянное здание, вы его не пропустите!\nАлекс: Идеально! Большое спасибо за вашу помощь.\nМестный: Пожалуйста! Удачи на встрече.\n\n💡 А2 ПРО-ЛАЙФХАК: ПРАВИЛО ПОВТОРЕНИЯ (ЭХО)\nЗаметил, как Алекс в диалоге кратко повторяет указания местного жителя: \"Turn left at the lights and walk through the park. Got it\"? Делай так всегда! Во-первых, это помогает тебе самому зафиксировать маршрут в памяти. Во-вторых, собеседник сразу увидит, что ты его правильно понял, и при необходимости вовремя поправит тебя.\n\n🔥 Твое мини-задание: Представь, что ты ищешь ИТ-хаб. Произнеси вслух громко и уверенно самый вежливый вопрос этого урока: Excuse me, could you tell me the way to the tech hub? Отточи эту интонацию!","button_text":"Перейти к тестам ➡️"}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


