INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  55,
  1,
  'theory',
  '{"text":"🎬 ФИКСИРУЕМ БРОНЬ С LEXI: ПОДГОТОВКА ИНФРАСТРУКТУРЫ ДЛЯ ПОЕЗДКИ\n\nПривет! На связи Lexi. Мы уже умеем координировать логистику, выбирать транспорт и рассчитывать время в пути. Теперь пора разобраться с тем, где мы будем жить и как зафиксировать за собой лучшие места. Будь то аренда апартаментов в Бангкоке, бронирование отеля в Москве для участия в хакатоне или заказ авиабилетов.\n\nНа уровне А2 нам важно не просто нажать кнопку «Забронировать» в агрегаторе. Нам нужно уметь общаться со службой поддержки: запросить подтверждение бронирования для визы, уточнить условия отмены, перенести даты или договориться о раздельной оплате.\n\nВключайте видео! Мы разберем главные типы номеров, опции тарифов и ключевые фразы, которые сэкономят ваши деньги при форс-мажорах.","video_url":"https://vk.com/video-230370533_456239081","vk_attachment":"video-230370533_456239081","button_text":"К теории бронирования ➡️"}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  55,
  2,
  'theory',
  '{"text":"✨ УРОК 25. КЛАССИФИКАЦИЯ ТАРИФОВ И СИНТАКСИС ДАТ\n\nДавай разберем архитектуру правильного бронирования на английском:\n\n1. ТИПЫ НОМЕРОВ И КРОВАТЕЙ (ТИПИЧНЫЕ ДЕТАЛИ ТЗ)\n• Single room [сингл рум] — одноместный номер (с одной односпальной кроватью).\n• Double room [дабл рум] — двухместный номер (с одной большой двуспальной кроватью для пар).\n• Twin room [туин рум] — двухместный номер (с двумя раздельными односпальными кроватями — идеально для коллег в командировке).\n• High-speed Wi-Fi connection — наличие быстрого интернета (критически важный параметр для удаленной работы).\n\n2. УСЛОВИЯ ТАРИФОВ (ФИНАНСОВЫЕ ПАРАМЕТРЫ)\n• Book in advance [бук ин эдвáнс] — бронировать заранее.\n• Free cancellation [фри кэнсэлэ́йшн] — бесплатная отмена бронирования.\n• Non-refundable [нон-рифáндабл] — невозвратный тариф (деньги при отмене сгорают, но сам тариф обычно дешевле).\n• Booking confirmation [бу́кинг конформэ́йшн] — подтверждение бронирования.\n\n3. СИНТАКСИС ДАТ И ПРЕДЛОГОВ (КАК НЕ ДОПУСТИТЬ ОШИБКУ В СРОКАХ)\nКогда мы указываем временной интервал проживания, мы используем связку предлогов FROM... TO... (с... по...).\nПример: I want to book a room from July 10th to July 15th. (Я хочу забронировать номер с 10 по 15 июля).\nЕсли мы указываем количество ночей, мы берем предлог FOR:\nПример: We reserved an apartment for 5 nights. (Мы забронировали апартаменты на 5 ночей).","button_text":"Понятно, дальше ➡️"}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  55,
  3,
  'theory',
  '{"text":"📖 ЖИВОЙ МИКРО-ДИАЛОГ: КОРПОРАТИВНОЕ БРОНИРОВАНИЕ ЖИЛЬЯ\n\nДавай послушаем, как основатель ИТ-студии Алекс и его партнер Марина звонят в службу поддержки отеля, чтобы организовать комфортное проживание во время предстоящей рабочей поездки:\n\nReceptionist: Good morning! Welcome to the Grand Tech Hotel support. How can I help you?\nMarina: Hello! We want to book a room for our business trip next month, from August 5th to August 12th. \nReceptionist: Excellent. What type of room do you prefer?\nMarina: We need a double room with a quiet workspace and high-speed Wi-Fi. \nReceptionist: No problem, all our corporate rooms have excellent internet parameters. Do you prefer a flexible rate or a non-refundable option?\nAlex: We need free cancellation because our project roadmap can change. \nReceptionist: Understood. The rate with free cancellation is two hundred dollars ($200) per night.\nAlex: That is a reasonable price. Can you charge our company credit card and send a corporate invoice to our email?\nReceptionist: Yes, of course. Please send your details. I will send the booking confirmation soon.\nMarina: Perfect, thank you!\n\n🇷🇺 ПЕРЕВОД ДЛЯ ПРОВЕРКИ:\n\nАдминистратор: Доброе утро! Добро пожаловать в службу поддержки Grand Tech Hotel. Чем я могу вам помочь?\nМарина: Здравствуйте! Мы хотим забронировать номер для нашей командировки в следующем месяце, с 5 по 12 августа. (from August 5th to August 12th — синтаксис дат).\nАдминистратор: Отлично. Какой тип номера вы предпочитаете?\nМарина: Нам нужен двухместный номер с тихой рабочей зоной и высокоскоростным Wi-Fi. (double room, high-speed Wi-Fi).\nАдминистратор: Без проблем, во всех наших корпоративных номерах отличные параметры интернета. Вы предпочитаете гибкий тариф или невозвратный вариант? (non-refundable option).\nАлекс: Нам нужна бесплатная отмена, потому что дорожная карта нашего проекта может измениться. (free cancellation).\nАдминистратор: Понятно. Тариф с бесплатной отменой составляет 200 долларов за ночь.\nАлекс: Это разумная цена. Вы можете списать средства с нашей корпоративной кредитной карты и отправить инвойс (счет) на нашу электронную почту? (send a corporate invoice).\nАдминистратор: Да, конечно. Пожалуйста, пришлите ваши реквизиты. Я скоро отправлю подтверждение бронирования. (booking confirmation).\nМарина: Идеально, спасибо!\n\n💡 А2 ПРО-ЛАЙФХАК ДЛЯ ПЕРЕПИСКИ:\nЕсли вам нужно официально отменить или изменить бронь через email, используйте короткий и вежливый шаблон: I would like to cancel my reservation. My booking number is XXX. (Я бы хотел отменить свое бронирование. Номер брони — XXX). Это избавит вас от необходимости писать длинные объяснения.\n\n🔥 Твое мини-задание: Представь, что ты заселяешься в отель и просишь пароль от интернета. Произнеси вслух четко и бегло: \"Excuse me, what is the Wi-Fi password?\". Почувствуй себя уверенно!","button_text":"Перейти к тестам ➡️"}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


