INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  62,
  5,
  'quiz_choice',
  '{"question":"Тест на хронологию (цепочку действий). Как правильно перевести на английский язык фразу: ''Я проснулся, выпил стакан воды и вышел из дома''?","options":[{"id":"a","text":"I woke up, drank a glass of water, and left the house.","is_correct":true},{"id":"b","text":"I was waking up, was drinking a glass of water, and was leaving the house.","is_correct":false},{"id":"c","text":"I woke up, was drinking a glass of water, and left the house.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — А. Если действия происходили последовательно, одно за другим, создавая классическую цепочку событий, используется исключительно Past Simple. Форма Continuous здесь была бы ошибкой."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
