  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  62,
  6,
  'quiz_choice',
  '{"question":"Ловушка уровня B1: Глаголы состояния в прошлом. Вспомните, как ведут себя Stative Verbs, и выберите грамматически верный вариант предложения:","options":[{"id":"a","text":"When we got lost in London, I wasn''t knowing the way back to the hotel.","is_correct":false},{"id":"b","text":"When we got lost in London, I didn''t know the way back to the hotel.","is_correct":true},{"id":"c","text":"While we were getting lost, I wasn''t knowing the way back to the hotel.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — B. Глагол ''know'' (знать) — это глагол состояния. Даже если вы описываете конкретный затяжной момент в прошлом, его ЗАПРЕЩЕНО использовать во времени Continuous (wasn''t knowing — грубая ошибка). В таких случаях мы всегда используем Past Simple (didn''t know)."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


