VALUES (
  66,
  4,
  'quiz_choice',
  '{"question":"Главная битва английского языка: Present Perfect против Past Simple. Выберите предложение, которое правильно описывает ЖИЗНЕННЫЙ ОПЫТ (без указания конкретного времени в прошлом):","options":[{"id":"a","text":"I have visited London in 2018.","is_correct":false},{"id":"b","text":"I visited London several times in my life.","is_correct":false},{"id":"c","text":"I have visited London several times in my life.","is_correct":true}],"explanation_if_wrong":"Правильный ответ — С. Если мы говорим о жизненном опыте в целом («несколько раз в жизни») и не называем конкретный год или день, используется Present Perfect. Вариант А ошибочен, так как точная дата (in 2018) жестко требует Past Simple."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
