)
VALUES (
  66,
  5,
  'quiz_choice',
  '{"question":"Тест на маркеры времени ''already'' и ''yet''. Вам нужно сказать другу: «Я уже прочитал эту книгу, но я еще не досмотрел сериал». Выберите безупречный вариант:","options":[{"id":"a","text":"I have already read this book, but I haven''t finished the TV series yet.","is_correct":true},{"id":"b","text":"I have yet read this book, but I haven''t finished the TV series already.","is_correct":false},{"id":"c","text":"I already have read this book, but I haven''t yet finished the TV series.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — А. Маркер ''already'' (уже) используется в утверждениях и ставится между have и глаголом. Маркер ''yet'' (еще не) используется в отрицаниях и строго ставится в самый конец предложения."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
  order_num,
