INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  69,
  6,
  'quiz_choice',
  '{"question":"Ловушка архитектуры рассказа. Вам нужно начать свою историю на встрече выпускников: «Я прожил очень интересную жизнь. Например, в прошлом году я прыгнул с парашютом». Выберите безупречную грамматическую связку времен:","options":[{"id":"a","text":"I lived a very interesting life. For example, last year I have jumped with a parachute.","is_correct":false},{"id":"b","text":"I have lived a very interesting life. For example, last year I was jumping with a parachute.","is_correct":false},{"id":"c","text":"I have lived a very interesting life. For example, last year I jumped with a parachute.","is_correct":true}],"explanation_if_wrong":"Правильный ответ — С. По канонам B-уровня мы открываем рассказ через Present Perfect (I have lived), презентуя свой жизненный багаж в целом. Но как только мы переходим к примеру с точной датой (last year), мы обязаны переключиться на обычный Past Simple (jumped)."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


