  content_json
)
VALUES (
  71,
  4,
  'quiz_choice',
  '{"question":"Проверка на точечный стоп-кадр времени. Вы хотите рассказать другу: «Вчера ровно в полдень (at noon) я плавал в бассейне, поэтому не мог ответить на твое сообщение». Выберите идеальный вариант:","options":[{"id":"a","text":"Yesterday at noon, I swam in the swimming pool.","is_correct":false},{"id":"b","text":"Yesterday at noon, I was swimming in the swimming pool.","is_correct":true},{"id":"c","text":"Yesterday at noon, I used to swim in the swimming pool.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — B. Если указан конкретный точечный момент времени в прошлом (в полдень, в 5 вечера, ровно в 7:30), это сигнал для создания стоп-кадра в Past Continuous. Мы показываем, что в эту секунду процесс уже развивался."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
