  step_type,
  content_json
)
VALUES (
  71,
  5,
  'quiz_choice',
  '{"question":"Тест на отрицательную форму и промежутки времени. Как правильно перевести фразу: «С двух до четырех часов дня мы НЕ смотрели телевизор, мы приводили в порядок комнату»?","options":[{"id":"a","text":"From two to four PM we weren''t watching TV, we were tidying up the room.","is_correct":true},{"id":"b","text":"From two to four PM we didn''t watch TV, we tidied up the room.","is_correct":false},{"id":"c","text":"From two to four PM we didn''t watching TV, we were tidy up the room.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — А. Для промежутков времени «с... до...» (from... to...) в прошлом требуется Past Continuous. Отрицание строится с помощью weren''t (we were not) + глагол с окончанием -ing."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
