VALUES (
  73,
  4,
  'quiz_choice',
  '{"question":"Проверка на параллельные процессы. Вы хотите сказать: «Пока моя сестра рисовала картину, я читал интересную книгу». Оба действия долгие и происходят одновременно. Выберите идеальный вариант:","options":[{"id":"a","text":"When my sister was painting a picture, I was reading an interesting book.","is_correct":false},{"id":"b","text":"While my sister was painting a picture, I was reading an interesting book.","is_correct":true},{"id":"c","text":"While my sister painted a picture, I read an interesting book.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — B. Для связи двух длительных процессов, которые развиваются параллельно в одно и то же время, в английском языке используется исключительно союз ''While'' (пока / в то время как) в сочетании с Past Continuous."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
