INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  73,
  6,
  'quiz_choice',
  '{"question":"Ловушка геометрии союзов уровня B1. Выберите предложение, в котором союзы распределены грамматически безупречно:","options":[{"id":"a","text":"While the phone rang, I was taking a relaxing shower.","is_correct":false},{"id":"b","text":"The phone rang while I was taking a relaxing shower.","is_correct":true},{"id":"c","text":"The phone was ringing while I took a relaxing shower.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — B. Короткое внезапное действие (телефон зазвонил — Past Simple) прерывает длительный фоновый процесс (я принимал душ — Past Continuous). Союз ''while'' обязан стоять непосредственно перед длительным процессом."}'
)
