  step_type,
  content_json
)
VALUES (
  75,
  4,
  'quiz_choice',
  '{"question":"Проверка архитектуры начала истории. Вы хотите начать свой рассказ перед друзьями: «В моей жизни происходило много странных вещей, но прошлым летом я пережил самый удивительный день». Выберите грамматически безупречный вариант перехода от опыта к деталям:","options":[{"id":"a","text":"Many strange things happened in my life, but last summer I have experienced the most amazing day.","is_correct":false},{"id":"b","text":"Many strange things have happened in my life, but last summer I experienced the most amazing day.","is_correct":true},{"id":"c","text":"Many strange things were happening in my life, but last summer I was experiencing the most amazing day.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — B. По правилам уровня B1, мы заявляем о жизненном опыте в целом через Present Perfect (Many strange things have happened). Но как только мы переходим к конкретному случаю с точной датой в прошлом (last summer), мы обязаны переключиться на Past Simple (I experienced)."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
