INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  88,
  6,
  'quiz_choice',
  '{"question":"Ловушка непредвиденных обстоятельств (IF). Вы обсуждаете планы на загородный пикник в воскресенье. Вы хотите сказать вашим близким: «Если вдруг пойдет сильный дождь, мы просто останемся дома». Какой союз здесь уместен, учитывая, что дождь — это лишь возможный форс-мажор?","options":[{"id":"a","text":"If it rains heavily on Sunday, we will just stay at home.","is_correct":true},{"id":"b","text":"When it rains heavily on Sunday, we will just stay at home.","is_correct":false},{"id":"c","text":"If it will rain heavily on Sunday, we will just stay at home.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — А. Поскольку дождь в воскресенье является лишь вероятной возможностью, а не вашим стопроцентным планом, необходимо использовать союз условия ''If'' (если). Использование ''When'' (вариант B) означало бы, что вы гарантированно ждете дождя и планируете его. Вариант С содержит запрещенный ''will'' после ''if''."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


