INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  98,
  5,
  'quiz_choice',
  '{"question":"Тест на употребление связующих оборотов. Выберите предложение, в котором выражение для демонстрации противоположной, негативной стороны ситуации использовано абсолютно уместно и без ошибок:","options":[{"id":"a","text":"The hotel was very close to the beach. On the flip side, the rooms were incredibly noisy.","is_correct":true},{"id":"b","text":"The hotel was very close to the beach. On the plus side, the rooms were incredibly noisy.","is_correct":false},{"id":"c","text":"The hotel was very close to the beach. On the downside side, the rooms were incredibly noisy.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант А. Оборот ''On the flip side'' (с другой стороны / на оборотной стороне) отлично вводит контрастный негативный факт после позитивного. Вариант B ошибочен, так как ''On the plus side'' вводит только преимущества, а шумные комнаты — это минус. Вариант C содержит грамматическую ошибку: правильно говорить либо ''On the downside'', либо ''A significant downside is...'', дублировать слово ''side'' нельзя."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


