VALUES (
  102,
  4,
  'quiz_choice',
  '{"question":"Тест на выражение критики и сожаления в прошлом (Should have). Вам нужно сказать коллеге: «Вам СЛЕДОВАЛО предупредить меня о переносе встречи заранее (но Вы этого не сделали, и я приехал зря)». Выберите безупречный вариант:","options":[{"id":"a","text":"You should have informed me about the meeting cancellation in advance.","is_correct":true},{"id":"b","text":"You should inform me about the meeting cancellation in advance.","is_correct":false},{"id":"c","text":"You should had informed me about the meeting cancellation in advance.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант А. Конструкция ''should have + 3-я форма глагола'' (informed) используется для выражения сожаления или критики относительно прошлых событий. Вариант B относится к настоящему или будущему времени (совет на будущее). Вариант C грамматически ошибочен, так как в этой конструкции всегда используется неизменяемый глагол ''have''."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
