INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  106,
  6,
  'quiz_choice',
  '{"question":"Тест на использование альтернативных модальных глаголов. Вам нужно выразить осторожное гипотетическое предположение: «Если бы мы переехали в пригород, мы, ВОЗМОЖНО, БЫЛИ БЫ более счастливы (но мы не уверены на 100%)». Выберите идеальный вариант:","options":[{"id":"a","text":"If we moved to the countryside, we might be much happier.","is_correct":true},{"id":"b","text":"If we would move to the countryside, we might be much happier.","is_correct":false},{"id":"c","text":"If we moved to the countryside, we would can be much happier.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант А. Для выражения неуверенности или осторожной гипотезы в главном предложении вместо ''would'' используется модальный глагол ''might''. Вариант B ошибочен, так как глагол ''would'' категорически запрещено ставить в условную часть сразу после слова ''If''. Вариант C содержит грубую ошибку ''would can'' — модальные глаголы нельзя ставить друг за другом, для этого существует форма ''could''."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lessons (
  id,
  level_id,
  order_num,
  title,
  description,
  is_premium
)
VALUES (
  107,
  4,
  17,
  'Third Conditional: Виртуальная машина времени',
