)
VALUES (
  110,
  6,
  'quiz_choice',
  '{"question":"Тест на ловушки структуры WHAT IF. Выберите предложение, в котором воображаемый риск в будущем описан БЕЗ единой грамматической ошибки:","options":[{"id":"a","text":"What if the project team will reject our suggestions tomorrow?","is_correct":false},{"id":"b","text":"What if the project team rejects our suggestions tomorrow?","is_correct":false},{"id":"c","text":"What if the project team rejected our suggestions tomorrow? What would we do?","is_correct":true}],"explanation_if_wrong":"Правильный ответ — вариант С. Конструкция ''What if'' для выражения маловероятного, чисто гипотетического сценария («А что если вдруг...») требует после себя глагол в прошедшем времени Past Simple (rejected) для согласования с последующим ''would'' в вопросе ''What would we do?''. Варианты А и B не соответствуют продвинутому стандарту выражения воображаемых гипотез."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


