  content_json
)
VALUES (
  116,
  4,
  'quiz_choice',
  '{"question":"Тест на сочетаемость слов (Collocations). Вам нужно заявить на деловой встрече: «Я ТВЕРДО ВЕРЮ, что наш новый проект будет иметь огромный успех». Выберите грамматически и лексически безупречный вариант:","options":[{"id":"a","text":"I very believe that our new project will be a huge success.","is_correct":false},{"id":"b","text":"I strongly am believing that our new project will be a huge success.","is_correct":false},{"id":"c","text":"I firmly believe that our new project will be a huge success.","is_correct":true}],"explanation_if_wrong":"Правильный ответ — вариант С. Наречие ''firmly'' (твердо) является устойчивым партнером для глагола ''believe'' при выражении сильного мнения. Вариант А ошибочен, так как слово ''very'' нельзя ставить перед глаголами. Вариант B нарушает правила грамматики: глагол состояния ''believe'' запрещено использовать во временах группы Continuous."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
