)
VALUES (
  120,
  4,
  'quiz_choice',
  '{"question":"Проверка на интеграцию условных предложений (Mixed Conditionals). Выберите предложение, которое описывает ситуацию, где ПРОШЛОЕ решение или событие напрямую влияет на НАСТОЯЩЕЕ состояние объекта:","options":[{"id":"a","text":"If we had backed up the files yesterday, we would have saved the data.","is_correct":false},{"id":"b","text":"If we backed up the files yesterday, we would save the data now.","is_correct":false},{"id":"c","text":"If we had backed up the files yesterday, we wouldn''t be in trouble right now.","is_correct":true}],"explanation_if_wrong":"Правильный ответ — вариант С. Это классическое смешанное условное предложение (Mixed Conditional). Условие осталось в прошлом (Past Perfect: ''had backed up''), а результат напрямую влияет на текущий момент в настоящем (wouldn''t be + маркер ''right now''). Вариант А — это чистый Third Conditional (всё в прошлом), а вариант B грамматически ошибочен."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


