INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  126,
  6,
  'quiz_choice',
  '{"question":"Внимание, классическая ловушка продвинутого уровня (Dangling Participle)! Помня о том, что субъект действия в причастном обороте обязан совпадать с подлежащим главного предложения, найдите ЕДИНСТВЕННЫЙ грамматически верный вариант:","options":[{"id":"a","text":"Walking into the laboratory, the smell of lavender surprised the perfumer.","is_correct":false},{"id":"b","text":"Walking into the laboratory, the perfumer was surprised by the smell of lavender.","is_correct":true},{"id":"c","text":"Walking into the laboratory, a surprise caught the perfumer because of the smell.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант B. В лабораторию входил именно парфюмер (the perfumer), поэтому он и должен быть подлежащим главного предложения. В варианте А получается абсурд: как будто запах лаванды сам шёл по коридору и заходил в лабораторию."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


