  step_type,
  content_json
)
VALUES (
  129,
  6,
  'quiz_choice',
  '{"question":"Вам нужно корректно составить фразу: «Она обвинила Марка в том, что он сорвал переговоры». Выберите вариант, в котором управление предлогами и форма глагола BLAME выполнены без ошибок:","options":[{"id":"a","text":"She blamed Mark to disrupt the negotiations.","is_correct":false},{"id":"b","text":"She blamed Mark for disrupting the negotiations.","is_correct":true},{"id":"c","text":"She blamed on Mark for disrupting the negotiations.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант B. Глагол «blame» имеет строго зафиксированное управление: blame + someone + FOR + doing something (герундий). Вариант А нарушает это правило инфинитивом, а вариант C использует лишний предлог on после самого глагола."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
