)
VALUES (
  130,
  4,
  'quiz_choice',
  '{"question":"Вам необходимо составить предложение для официального коммерческого предложения. Вы хотите сказать: «Мы должны тщательно изучить этот вопрос, прежде чем принимать финальное решение». Выберите вариант, который идеально соответствует строгому формальному стилю C1:","options":[{"id":"a","text":"We need to look into this matter before we make up our minds.","is_correct":false},{"id":"b","text":"A thorough investigation of this matter must be conducted prior to reaching a final decision.","is_correct":true},{"id":"c","text":"We must thoroughly investigate this issue before making up our mind.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант B. Здесь использованы главные маркеры формального стиля: пассивный залог (must be conducted), изысканный предлог «prior to» вместо простого «before» и номинализация (investigation, decision) вместо глаголов. Варианты А и С содержат разговорные фразовые глаголы (look into, make up one''s mind), недопустимые в строгом официальном документе."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
