  content_json
)
VALUES (
  132,
  5,
  'quiz_choice',
  '{"question":"Вы хотите поэтично и весомо сказать инвесторам или коллегам: «Этот контракт является живым свидетельством нашего взаимного доверия». Выберите верное управление для идиомы «A testament...»:","options":[{"id":"a","text":"This contract is a testament for our mutual trust.","is_correct":false},{"id":"b","text":"This contract is a testament to our mutual trust.","is_correct":true},{"id":"c","text":"This contract is a testament with our mutual trust.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант B. Устойчивое выражение «a testament to something» (свидетельство / доказательство чего-либо) в английском языке требует после себя строго предлог «to». Использование предлогов «for» или «with» является частой ошибкой тех, кто переводит фразу дословно с русского."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
