  step_type,
  content_json
)
VALUES (
  133,
  4,
  'quiz_choice',
  '{"question":"Вам нужно начать Ваше выступление на дебатах с вежливой уступки оппонентам: «Допустим/Разумеется, этот план имеет определенные экономические преимущества, однако...». Выберите идеальное вводное слово уровня C1:","options":[{"id":"a","text":"Granted, this plan has certain economic advantages, however...","is_correct":true},{"id":"b","text":"Grounds, this plan has certain economic advantages, however...","is_correct":false},{"id":"c","text":"Granting, this plan has certain economic advantages, however...","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант А. Слово «Granted» в начале предложения используется в продвинутом английском как вводное слово для уступки оппоненту («Допустим», «Разумеется», «Да, это так, но...»). Варианты B и C грамматически не имеют такого значения."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
