INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  138,
  5,
  'quiz_choice',
  '{"question":"Вам нужно очень вежливо, но твердо попросить подрядчика ускорить процесс разработки проектной документации, так как поджимают сроки. Какое слово идеально заменит простое выражение «speed up» в стиле C1?","options":[{"id":"a","text":"We would highly appreciate it if you could expand this process.","is_correct":false},{"id":"b","text":"We would highly appreciate it if you could exchange this process.","is_correct":false},{"id":"c","text":"We would highly appreciate it if you could expedite this process.","is_correct":true}],"explanation_if_wrong":"Правильный ответ — вариант C. Глагол «expedite» переводится как «ускорять, содействовать быстрейшему исполнению (официальных процедур или процессов)». Это эталонное бизнес-слово. Вариант А означает «расширять», а вариант В — «обменивать»."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


