  step_type,
  content_json
)
VALUES (
  142,
  1,
  'theory',
  '{"text":"👋 ИСКУССТВО ДИСТИЛЛЯЦИИ МЫСЛИ: ВЫДЕЛЯЕМ ГЛАВНОЕ С LEXI  \n\n  Приветствую Вас на двадцать втором уроке нашего продвинутого модуля! На связи Lexi. Умение читать длинные и сложные тексты — это лишь половина успеха. На уровне C1 от Вас требуется способность мгновенно сжимать огромные объемы информации до нескольких емких, точных и престижных предложений. Это навык стратегического обобщения и синтеза.  \n\n  Когда Вы готовите аналитический обзор для руководства, выступаете перед коллегами или изучаете масштабный международный доклад, Вам нужно уметь мгновенно отсекать фоновые примеры и лирические отступления от главного тезиса автора. В английском языке для этого существует особый класс лексики — речевые инструменты дистилляции смысла.  \n\n  Мы научимся использовать изысканные глаголы вроде *encapsulate*, *distill*, фразовые обороты *boil down to* и устойчивые концепты вроде *the crux*. Чтобы сделать этот урок максимально увлекательным, мы перенесемся во Всемирный архив памяти — уникальное подземное хранилище на полярном архипелаге Шпицберген, где консервируются цифровые копии главных культурных и научных достижений человечества.  \n\n  Включайте лекционное видео! Давайте научимся зреть в самый корень любого текста.","video_url":"https://vk.com/video-230370533_456239171","vk_attachment":"video-230370533_456239171","button_text":"Открыть аналитический обзор ➡️"}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;


INSERT INTO lesson_steps (
  lesson_id,
  order_num,
