INSERT INTO lesson_steps (
  lesson_id,
  order_num,
  step_type,
  content_json
)
VALUES (
  150,
  6,
  'quiz_choice',
  '{"question":"Тест на номинальное перестроение и синтаксис. Вам нужно перевести фразу из отчета: «После того как мы тщательно изучили эти странные явления, контракт был официально подписан». Выберите наиболее статусную фразу:","options":[{"id":"a","text":"Having thoroughly investigated these strange phenomenons, the contract was ratified.","is_correct":false},{"id":"b","text":"Subsequent to a thorough investigation of these anomalous phenomena, the contract was ratified.","is_correct":true},{"id":"c","text":"Subsequent to investigating these anomalous phenomenas, we ratified the contract.","is_correct":false}],"explanation_if_wrong":"Правильный ответ — вариант B. Этот вариант демонстрирует высший пилотаж формального стиля С1: изысканный предлог «Subsequent to» (вслед за / после), глубокую номинализацию (thorough investigation) и латинскую форму множественного числа существительного «phenomena». Вариант А содержит ошибку «Dangling Participle» (контракт не мог сам изучать явления), а вариант С использует вымышленную форму «phenomenas»."}'
)
ON CONFLICT(lesson_id, order_num) DO UPDATE SET
  step_type = excluded.step_type,
  content_json = excluded.content_json;

